import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-07-27","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-07-27","date":"2021-07-27T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph","分布式存储","Rook","LSO","代码审查","文档更新","用户集成测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-07-27.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-07-27.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-07-27.md"};function r(s,e,n,h,p,d){return t(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph Orchestrator Meeting于2021年7月27日举行，主要讨论了Ceph存储系统的开发进展，特别是Rook和Local Storage Operator (LSO)的集成问题。会议涉及代码审查、文档更新、用户集成测试以及未来工作计划等多个议题。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>代码审查与集成测试</strong></p><ul><li>讨论了如何处理Pull Request (PR)中的评论和权限问题。</li><li>讨论了在代码中设置用户“dashboard”的问题，以及需要进行的集成测试。</li></ul></li><li><p><strong>文档更新与用户反馈</strong></p><ul><li>讨论了删除部分文档的问题，特别是关于“scheme nivea”选项的保留价值。</li><li>计划安排会议解决这些松散的结尾并推进验证请求 (VR)。</li></ul></li><li><p><strong>Rook与LSO的集成</strong></p><ul><li>讨论了Rook项目中关于OSD（Object Storage Daemon）的创建和移除的问题。</li><li>确认需要对Rook进行修改以支持OSD的移除，并讨论了可能的短期和长期解决方案。</li></ul></li><li><p><strong>LSO的未来发展</strong></p><ul><li>讨论了LSO的当前状态和未来发展方向，包括与Topol LVM的合作可能性。</li><li>确认需要与OpenShift的产品管理团队进行进一步的沟通，以确定LSO的未来发展路径。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>Alfonso将继续处理PR中的评论，并进行相关的集成测试。</li><li>计划安排会议解决文档和用户集成的问题。</li><li>确认需要对Rook进行修改以支持OSD的移除，并讨论了可能的短期和长期解决方案。</li><li>确认需要与OpenShift的产品管理团队进行进一步的沟通，以确定LSO的未来发展路径。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Alfonso将继续处理PR中的评论，并进行相关的集成测试。</li><li>计划安排会议解决文档和用户集成的问题。</li><li>确认需要对Rook进行修改以支持OSD的移除，并讨论了可能的短期和长期解决方案。</li><li>确认需要与OpenShift的产品管理团队进行进一步的沟通，以确定LSO的未来发展路径。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后结束，参与者计划在下周继续跟进相关工作。</p>',11)])])}const _=a(i,[["render",r]]);export{u as __pageData,_ as default};
